
const mongoose = require("mongoose");

const sessionSchema = new mongoose.Schema(
  {
    // Unique session ID generated by mobile app
    sessionId: {
      type: String,
      required: [true, "Session ID is required"],
      unique: true,
      trim: true,
      index: true
    },

    // Device that started this session
    deviceId: {
      type: String,
      required: [true, "Device ID is required"],
      trim: true,
      index: true
    },

    // Patient being monitored
    patientId: {
      type: String,
      required: [true, "Patient ID is required"],
      trim: true,
      index: true
    },

    // Session lifecycle
    status: {
      type: String,
      enum: ["active", "completed", "interrupted"],
      default: "active",
      required: true
    },

    // Session start time
    startedAt: {
      type: Date,
      required: true,
      default: Date.now
    },

    // Session completion time
    endedAt: {
      type: Date,
      default: null
    },

    // Last successful server synchronization time
    lastSyncedAt: {
      type: Date,
      default: null
    }
  },
  {
    timestamps: true,
    versionKey: false
  }
);

// Useful for retrieving a device's session history
sessionSchema.index({
  deviceId: 1,
  startedAt: -1
});

sessionSchema.index({
  patientId: 1,
  startedAt: -1
});

const Session = mongoose.model("Session", sessionSchema);

module.exports = Session;
